#!/usr/bin/env python3
"""Propose exact-rational critical-constant enclosures; Lean checks all bounds."""
from fractions import Fraction as F
from decimal import Decimal, getcontext, ROUND_FLOOR
from pathlib import Path
getcontext().prec=65
lines=['import SparseLowerTail.Section05.CoverConstantBounds','',
'/-! Checked sharper critical constants for interval replay. Generated by',
'`tools/generate_cover_constant_digits.py`; decimal computations only propose bounds. -/',
'noncomputable section','namespace SparseLowerTail.Section05','open Section04 Numerics']
def emit(s=''):lines.append(s)
def q(x):
 x=F(x);return f'({x.numerator}/{x.denominator} : ℝ)'
def dec(x):return Decimal(x.numerator)/Decimal(x.denominator)
def enclose(d,p=14):
 n=int((d*10**p).to_integral_value(rounding=ROUND_FLOOR));return F(n-1,10**p),F(n+2,10**p)
def logcert(name,x,k,n):
 l,u=enclose(dec(x).ln());s=2**k
 emit(f'theorem {name} : Bounds (Real.log {q(x)}) {q(l)} {q(u)} := by')
 emit(f'  have h := Real.abs_log_sub_add_sum_range_le (x := {q(1-s*x)}) (by norm_num) {n}')
 emit('  norm_num [Finset.sum_range_succ] at h')
 emit('  have hl := (abs_le.mp h).1\n  have hu := (abs_le.mp h).2')
 if k:
  emit(f'  have he : Real.log {q(s*x)} = {k}*Real.log 2+Real.log {q(x)} := by')
  emit(f'    rw [show {q(s*x)} = (2:ℝ)^{k}*{q(x)} by norm_num,Real.log_mul (by norm_num) (by norm_num),Real.log_pow]')
  emit('    norm_num')
  emit('  rw [he] at hl hu\n  have h2l := log_two_bounds_22.1\n  have h2u := log_two_bounds_22.2')
 emit('  constructor <;> linarith\n');return l,u
al,au=F(1703401908,10**11),F(1703401909,10**11)
bl,bu=F(8493469443,10**10),F(8493469444,10**10)
lal,lau=logcert('cover_logA_lower_endpoint',al,6,16)
ual,uau=logcert('cover_logA_upper_endpoint',au,6,16)
lbl,lbu=logcert('cover_logB_lower_endpoint',bl,0,20)
ubl,ubu=logcert('cover_logB_upper_endpoint',bu,0,20)
emit('theorem criticalOmega_checked_bounds : Bounds criticalOmega (92312137/10^8) (92312139/10^8) := by')
emit('  have ha : Bounds criticalA '+q(al)+' '+q(au)+' := transition_digits.1.weaken (by norm_num) (by norm_num)')
emit('  have hb : Bounds criticalB '+q(bl)+' '+q(bu)+' := transition_digits.2.1.weaken (by norm_num) (by norm_num)')
emit('  have hla := ha.log_of_endpoints (by norm_num) cover_logA_lower_endpoint.1 cover_logA_upper_endpoint.2')
emit('  have hlb := hb.log_of_endpoints (by norm_num) cover_logB_lower_endpoint.1 cover_logB_upper_endpoint.2')
for tag,l,u,ll,uu in [('a',al,au,lal,uau),('b',bl,bu,lbl,ubu)]:
 corners=[l*ll,l*uu,u*ll,u*uu];ml,mu=min(corners),max(corners)
 # Exact endpoints; moderate denominator products, entirely rational.
 emit(f'  have hm{tag} : Bounds (critical{tag.upper()}*Real.log critical{tag.upper()}) {q(ml)} {q(mu)} := by')
 emit(f'    exact h{tag}.mul_corners hl{tag} '+' '.join(['(by norm_num)']*8))
 emit(f'  have he{tag} : Bounds (entropy critical{tag.upper()}) {q(ml-u+1)} {q(mu-l+1)} := by')
 emit(f'    convert (hm{tag}.sub h{tag}).add (Bounds.refl 1) using 1 <;> norm_num [entropy]')
emit('  have hg := hea.sub heb\n  have hn := hb.sub ha')
emit('  exact (hn.div_pos hg (by norm_num) (by norm_num)).weaken (by norm_num) (by norm_num)')
emit('''
theorem criticalTriangle_sharp_bounds : Bounds criticalTriangle
    (9217366866/10^12) (9217366881/10^12) := by
  exact (threshold_digits.pow (by norm_num) 3).weaken (by norm_num) (by norm_num)

end SparseLowerTail.Section05''')
(Path(__file__).resolve().parents[1]/'SparseLowerTail/Section05/CoverConstantDigits.lean').write_text('\n'.join(lines)+'\n')
